public boolean shouldPrintMessage(int timestamp, String message) {
    // Validate inputs
    if (message == null || timestamp < 0) {
        return false;
    }

    // Assume a field named 'lastPrinted' of type java.util.Map<String, Integer> exists.
    // Lazily initialize it if it hasn't been set up yet.
    if (lastPrinted == null) {
        lastPrinted = new java.util.HashMap<>();
    }

    Integer lastTime = lastPrinted.get(message);
    if (lastTime == null || timestamp - lastTime >= 10) {
        lastPrinted.put(message, timestamp);
        return true;
    }
    return false;
}

