private void enlarge(final int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("Size must be positive");
    }
    // Compute new capacity, checking for integer overflow
    int newCapacity = capacity + size;
    if (newCapacity < 0) { // overflow
        throw new OutOfMemoryError("Required capacity exceeds maximum array size");
    }
    // Allocate new array and copy existing data
    byte[] newData = new byte[newCapacity];
    if (data != null) {
        System.arraycopy(data, 0, newData, 0, Math.min(data.length, newCapacity));
    }
    // Replace old array and update capacity
    data = newData;
    capacity = newCapacity;
}

