private void putAbstractTypes(final int start, final int end) {
    // Validate that required fields are not null
    if (currentFrame == null) {
        throw new NullPointerException("currentFrame is null");
    }
    if (stackMapTableEntries == null) {
        throw new NullPointerException("stackMapTableEntries is null");
    }

    // Validate indices
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start or end indices");
    }

    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];
        if (type == null) {
            throw new NullPointerException("Type at index " + i + " is null");
        }

        int tag = type.getTag(); // JVMS verification_type_info tag
        int needed = 1; // at least the tag byte

        // OBJECT (tag 7) and UNINITIALIZED (tag 8) require an additional u2 field
        if (tag == 7 || tag == 8) {
            needed += 2;
        }

        // Ensure there is enough space in the buffer
        if (stackMapTableIndex + needed > stackMapTableEntries.length) {
            throw new IllegalStateException("StackMapTable entries buffer overflow");
        }

        // Write the tag
        stackMapTableEntries[stackMapTableIndex++] = (byte) tag;

        // Write the extra u2 field if required
        if (tag == 7) { // OBJECT
            int classIndex = type.getClassIndex();
            stackMapTableEntries[stackMapTableIndex++] = (byte) ((classIndex >> 8) & 0xFF);
            stackMapTableEntries[stackMapTableIndex++] = (byte) (classIndex & 0xFF);
        } else if (tag == 8) { // UNINITIALIZED
