        throw new IllegalArgumentException("Target type must be Character or char");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return s.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String to Character: length != 1");
        }
    }
    if (value instanceof Number) {
        long longVal = ((Number) value).longValue();
        if (longVal < 0 || longVal > 0xFFFF) {
            throw new IllegalArgumentException("Number out of char range");
        }
        return (char) longVal;
    }
    throw new IllegalArgumentException("Cannot convert type " + value.getClass().getName() + " to Character");
}

