private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("node cannot be null");
    }
    // Ensure the node is actually part of this list
    if (node.prev == null && node.next == null && head != node && tail != node) {
        throw new IllegalArgumentException("node is not part of this list");
    }
    if (size <= 0) {
        throw new IllegalStateException("list is empty");
    }

    // Adjust the previous node
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        // node is the head
        head = node.next;
    }

    // Adjust the next node
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        // node is the tail
        tail = node.prev;
    }

    // Clean up the removed node's links
    node.prev = null;
    node.next = null;

    // Update size
    size--;

    return true;
}

