private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start and stop nodes must not be null");
    }

    // Create a circulator starting at the given node
    OuterFaceCirculator circ = new OuterFaceCirculator(start);

    // If the start node already satisfies the predicate, return it immediately
    if (predicate.test(circ.getNode())) {
        return circ;
    }

    // If the start node is the stop node, return it
    if (circ.getNode().equals(stop)) {
        return circ;
    }

    // Traverse the outer face in the specified direction until we hit the stop node
    // or find a node that satisfies the predicate.
    // dir > 0 -> clockwise (next), dir < 0 -> counter‑clockwise (prev)
    while (true) {
        // Move to the next node in the chosen direction
        circ = (dir > 0) ? circ.next() : circ.prev();

        // If the circulator becomes null (should not happen in a well‑formed graph),
        // break out of the loop and return the stop node.
        if (circ == null) {
            break;
        }

        // If we have looped back to the start node without finding the stop node,
        // break to avoid an infinite loop.
        if (circ.getNode().equals(start)) {
            break;
        }

        // If the current node satisfies the predicate, return it
        if (predicate.test(circ.getNode())) {
            return circ;
        }

        // If we have reached the stop node, return it
        if (circ.getNode().equals(stop)) {
            return circ;
        }
    }

    // If we exit the loop without finding a satisfying node, return a circulator
    // positioned at the stop node.
    return new OuterFaceCirculator(stop);
}

