private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> result = new ArrayList<>();
    if (keys == null) {
        return result;
    }
    // Build a sorted list of non-null keys
    List<K> sortedKeys = new ArrayList<>();
    for (K key : keys) {
        if (key != null) {
            sortedKeys.add(key);
        }
    }
    try {
        Collections.sort(sortedKeys);
    } catch (ClassCastException e) {
        throw new IllegalArgumentException("All keys must be comparable", e);
    }
    for (K key : keys) {
        if (key == null) {
            result.add(null);
            continue;
        }
        int idx;
        try {
            idx = Collections.binarySearch(sortedKeys, key);
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("All keys must be comparable", e);
        }
        if (idx >= 0) {
            // Move to the last occurrence of the key
            while (idx + 1 < sortedKeys.size() && sortedKeys.get(idx + 1).equals(key)) {
                idx++;
            }
            result.add(idx);
        } else {
            int insertionPoint = -idx - 1;
            int lowerIndex = insertionPoint - 1;
            result.add(lowerIndex);
        }
    }
    return result;
}

