private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Handle null inputs gracefully
    if (graph == null || vertices == null) {
        return false;
    }

    // An empty set or a single vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    // Ensure all vertices are present in the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }

    // Convert to a list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();

    // Check every unordered pair of vertices
    for (int i = 0; i < n; i++) {
        V v1 = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V v2 = vertexList.get(j);
            // For undirected graphs, containsEdge(v1, v2) is sufficient.
            // For directed graphs, this will require an edge in the given direction.
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    return true;
}

