                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'v':
                    sb.append('\u000B'); // vertical tab
                    break;
                case '0':
                    sb.append('\0');
                    break;
                case 'x':
