                    int hexStart = i + 1;
                    int hexEnd = hexStart;
                    while (hexEnd < len && hexEnd - hexStart < 2 && Character.digit(input.charAt(hexEnd), 16) != -1) {
                        hexEnd++;
                    }
                    if (hexEnd > hexStart) {
                        try {
                            int value = Integer.parseInt(input.substring(hexStart, hexEnd), 16);
                            sb.append((char) value);
                        } catch (NumberFormatException e) {
                            // fallback: keep raw
                            sb.append('\\').append('x');
                            sb.append(input.substring(hexStart, hexEnd));
                        }
