public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        StringBuilder sb = new StringBuilder();

        // Timestamp
        long ts = event.getTimeStamp();
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        sb.append("[");
        sb.append(sdf.format(new java.util.Date(ts)));
        sb.append("] ");

        // Level
        sb.append(String.valueOf(event.getLevel()));
        sb.append(" ");

        // Thread name
        sb.append("[");
        sb.append(String.valueOf(event.getThreadName()));
        sb.append("] ");

        // Logger name
        sb.append(String.valueOf(event.getLoggerName()));
        sb.append(" - ");

        // Message
        sb.append(String.valueOf(event.getMessage()));

        // Throwable information, if any
        if (event.getThrowableInformation() != null) {
            java.lang.Throwable t = event.getThrowableInformation().getThrowable();
            if (t != null) {
                sb.append(System.lineSeparator());
                sb.append(t.toString());
                for (java.lang.StackTraceElement ste : t.getStackTrace()) {
                    sb.append(System.lineSeparator());
                    sb.append("\tat ").append(ste.toString());
                }
            }
        }

        return sb.toString();
    } catch (Exception e) {
        // Fallback in case of unexpected errors
        return "Error formatting LoggingEvent: " + e.getMessage();
    }
}

