public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    // Ensure the table is the view of the scroll pane
    if (pane.getViewport().getView() != table) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }
    try {
        // Select the specified row
        table.setRowSelectionInterval(row, row);
        // Scroll the table to make the row visible
        java.awt.Rectangle rect = table.getCellRect(row, 0, true);
        table.scrollRectToVisible(rect);
        // Repaint after a short delay to allow the table to render the selection
        final java.util.Timer timer = new java.util.Timer();
        timer.schedule(new java.util.TimerTask() {
            @Override
            public void run() {
                java.awt.EventQueue.invokeLater(() -> table.repaint());
                timer.cancel();
            }
        }, 50);
    } catch (Exception e) {
        // Ignore any exceptions to avoid disrupting the UI thread
    }
}

