public static void createConfigurationDirectory() {
    String osName = System.getProperty("os.name");
    String osVersion = System.getProperty("os.version");
    String basePath = null;

    try {
        if (osName != null && osName.startsWith("Windows") &&
            osVersion != null && osVersion.startsWith("5.0")) {
            // Windows 2000: create in Documents and Settings directory
            String userHome = System.getProperty("user.home");
            if (userHome != null) {
                File userHomeFile = new File(userHome);
                File parent = userHomeFile.getParentFile();
                if (parent != null) {
                    basePath = parent.getAbsolutePath();
                } else {
                    basePath = userHome;
                }
            } else {
                basePath = System.getProperty("user.home");
            }
        } else {
            // All other platforms: use user.home
            basePath = System.getProperty("user.home");
        }

        if (basePath == null) {
            throw new RuntimeException("Unable to determine base path for configuration directory.");
        }

        File configDir = new File(basePath, "lf5");
        if (!configDir.exists()) {
            if (!configDir.mkdirs()) {
                throw new RuntimeException("Failed to create configuration directory: " + configDir.getAbsolutePath());
            }
        }
    } catch (SecurityException se) {
        throw new RuntimeException("Permission denied while creating configuration directory.", se);
    }
}

