protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate FETCH_DATA_DURATION
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be a positive value");
    }
    // Validate input range
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    // If no duration, return empty list
    if (start == end) {
        return new ArrayList<>();
    }

    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long nextEnd;
        // Prevent overflow when adding FETCH_DATA_DURATION
        if (currentStart > Long.MAX_VALUE - FETCH_DATA_DURATION) {
            nextEnd = end;
        } else {
            nextEnd = currentStart + FETCH_DATA_DURATION;
            if (nextEnd > end) {
                nextEnd = end;
            }
        }
        ranges.add(new TimeRange(currentStart, nextEnd));
        currentStart = nextEnd;
    }
    return ranges;
}

