            if (inputProps == null || !inputProps.containsKey(key)) {
                diffProps.put(key, entry.getValue());
            }
        }

        if (diffProps.isEmpty()) {
            return null;
        }

        // Construct a new Mappings instance containing only the differing fields.
        return new Mappings(diffProps);
    } catch (Exception e) {
        // In case of any unexpected error, return null to indicate failure.
        return null;
    }
