static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate dayStep
    if (dayStep <= 0) {
        // Invalid step, return original bucket
        return timeBucket;
    }
    // Extract year, month, day from the long value YYYYMMDD
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Compute the compressed day
    int compressedDay = ((day - 1) / dayStep) * dayStep + 1;

    // Reconstruct the compressed time bucket
    return (long) year * 10000 + (long) month * 100 + compressedDay;
}

