public List<SequenceRange> buildSequenceRanges(){
    java.util.List<SequenceRange> ranges = new java.util.ArrayList<>();
    try {
        if (currentProfiles == null) {
            return ranges;
        }
        for (Profile profile : currentProfiles) {
            if (profile == null) {
                continue;
            }
            java.util.List<Segment> segments = profile.getSegments();
            if (segments == null) {
                continue;
            }
            for (Segment seg : segments) {
                if (seg == null) {
                    continue;
                }
                long start = seg.getStart();
                long end = seg.getEnd();
                if (end < start) {
                    long tmp = start;
                    start = end;
                    end = tmp;
                }
                ranges.add(new SequenceRange(start, end));
            }
        }
        // Optional: sort ranges by start position
        java.util.Collections.sort(ranges, new java.util.Comparator<SequenceRange>() {
            @Override
            public int compare(SequenceRange a, SequenceRange b) {
                return Long.compare(a.getStart(), b.getStart());
            }
        });
    } catch (Exception e) {
        // In case of any unexpected error, return what has been collected so far
    }
    return ranges;
}

