        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
        }
    }
    // Ensure internal buffer has enough capacity
    int newSize = size + byteLength;
    if (data == null || newSize > data.length) {
        int newCapacity = (data == null) ? newSize : Math.max(data.length * 2, newSize);
        byte[] newData = new byte[newCapacity];
        if (data != null) {
            System.arraycopy(data, 0, newData, 0, size);
        }
        data = newData;
    }
    // Copy bytes or insert null bytes
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            data[size + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
    }
    size = newSize;
    return this;
}

