private static int digitValue(final char c) {
    // Accept only ASCII digits and letters (both cases) for bases up to 36.
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    // Non-ASCII or non-digit characters are not accepted.
    return -1;
}

