public byte[] toByteArray() {
    try {
        // If the internal buffer is null or no data has been written, return an empty array.
        if (buf == null || count <= 0) {
            return new byte[0];
        }
        // Ensure we do not exceed the actual buffer length.
        int len = Math.min(count, buf.length);
        byte[] result = new byte[len];
        System.arraycopy(buf, 0, result, 0, len);
        return result;
    } catch (OutOfMemoryError e) {
        // Wrap the low‑level error in a RuntimeException to avoid leaking implementation details.
        throw new RuntimeException("Failed to allocate byte array", e);
    }
}

