private void checkIfPackedField() throws IOException {
    // If no tag has been read yet, there is nothing to check.
    if (currentTag == 0) {
        return;
    }

    // Validate the tag value.
    if (currentTag < 0) {
        throw new IOException("Invalid tag value: " + currentTag);
    }

    // Determine the wire type of the current tag.
    int wireType = WireFormat.getTagWireType(currentTag);

    // A packed repeated field is encoded as a length‑delimited field.
    // If the wire type matches, set the internal flag to indicate that
    // we are currently reading a packed field.  Otherwise, clear the flag.
    if (wireType == WireFormat.WIRETYPE_LENGTH_DELIMITED) {
        packedField = true;
    } else {
        packedField = false;
    }
}

